%[text] # Load Pretrained Weights
%%
%[text] ## Pre Trained Weight Files
% Define the available files and descriptions as an Nx2 cell array
PreTrainedWeighFiles = {
    'Denoising_ModelWeights.mat', 'Pretrained Model for Denoising childGT.jpeg corrupted with gaussian noise.\nDenoisingWorkflow.m contains the full pipeline.';
    'Inpainting_Removal_ModelWeights1.mat', 'Pretrained Model for restoring the spatially degraded image resulting from multiplying library.png with a mask.\nInpaintingWorkflowPt1.m contains the full pipeline.';
    'Inpainting_Removal_ModelWeights2.mat', 'Pretrained Model for restoring the spatially degraded image resulting from multiplying kate.png with a mask.\nInpaintingWorkflowPt2.m contains the full pipeline.';
    'SuperResolution_ModelWeights.mat', 'Pretrained Model for increasing the resolution the low resolution image resulting from downsampling child.jpeg.\nSuperResolutionWorkflow.m contains the full pipeline.'
    };

%%
%[text] ## Enter File of Interest
% Display the files and their descriptions to the user
fprintf('Available Pre-trained Weight Files:\n\n'); %[output:2d8879aa]
for i = 1:size(PreTrainedWeighFiles, 1) %[output:group:4ed65df3]
    % Parse the '\n' in your text to actual newlines with indentation
    formattedDesc = strrep(PreTrainedWeighFiles{i, 2}, '\n', sprintf('\n    '));
    fprintf('[%d] %s\n    %s\n\n', i, PreTrainedWeighFiles{i, 1}, formattedDesc); %[output:260ebf0e]
end %[output:group:4ed65df3]

% Prompt the user and validate the input
validInput = false;
while ~validInput
    userChoice = input('Enter a number (1-4) to select your file of interest: ');

    % Ensure input is a whole number strictly between 1 and 4
    if isnumeric(userChoice) && isscalar(userChoice) && ...
            mod(userChoice, 1) == 0 && userChoice >= 1 && userChoice <= size(PreTrainedWeighFiles, 1)
        validInput = true;
    else
        fprintf('Invalid entry. You must enter a whole number between 1 and %d.\n\n', size(PreTrainedWeighFiles, 1));
    end
end

% Assign ONLY the selected .mat filename to FileOfInterest
FileOfInterest = PreTrainedWeighFiles{userChoice, 1};

% Display the final selection
fprintf('\nSuccess! %s is now being loaded...\n', FileOfInterest); %[output:2f87e3bd]
%%
%[text] ## Load File of Interest
% 1. Load the saved model data
data = load(FileOfInterest);

% 2. Generate the raw prediction from the network
pred_raw = predict(data.net, data.net_input_saved);

% 3. Extract the numeric data from the dlarray and bring it to the CPU
img_raw = gather(extractdata(pred_raw));
img_avg = gather(extractdata(data.out_avg));

% 4. Format the arrays for image display
% Neural network outputs are often 4D (Height x Width x Channels x Batch).
% 'squeeze' removes any dimensions of size 1 (like the Batch dimension) to make it a standard 3D image.
img_raw = squeeze(img_raw);
img_avg = squeeze(img_avg);

% 5. Ensure the pixel values are in the standard [0, 1] range for imshow
img_raw = max(min(img_raw, 1), 0);
img_avg = max(min(img_avg, 1), 0);

% 6. Display the images side-by-side
%figure('Name', 'De Inpainted Results', 'Position', [100, 100, 900, 450]);
figure; %[output:658e01b6]

subplot(1, 2, 1); %[output:658e01b6]
imshow(img_raw); %[output:658e01b6]
title('Raw Network Prediction'); %[output:658e01b6]

subplot(1, 2, 2); %[output:658e01b6]
imshow(img_avg); %[output:658e01b6]
title('Averaged Output (out\_avg)'); %[output:658e01b6]

